## 数据范围

- `1 ≤ n ≤ 12`','["困难","回溯","位运算"]','逐行回溯，用列集合和两组对角线集合判断冲突。进一步可以用位掩码表示可放置位置，加速状态枚举。',0,0,'[{"input":"1\\n","output":"1\\n","isHidden":false},{"input":"4\\n","output":"2\\n","isHidden":false},{"input":"5\\n","output":"10\\n","isHidden":true},{"input":"8\\n","output":"92\\n","isHidden":true},{"input":"9\\n","output":"352\\n","isHidden":true}]','{"timeLimit":3000,"memoryLimit":262144,"outputLimitBytes":1048576}','{"mode":"function","className":"Solution","methodName":"totalNQueens","parameters":[{"name":"n","type":"int"}],"returnType":"int","resultSource":"return","comparator":{"type":"EXACT"},"harnessVersion":1,"judgeCases":[{"input":"{\\"n\\":1}","output":"1","isHidden":false},{"input":"{\\"n\\":4}","output":"2","isHidden":false},{"input":"{\\"n\\":5}","output":"10","isHidden":true},{"input":"{\\"n\\":8}","output":"92","isHidden":true},{"input":"{\\"n\\":9}","output":"352","isHidden":true}]}',1,1,0,0,@admin_id,0,0,24 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question_public_number WHERE problemNo=24);
